-- Sprint 10 synchronization and least-privilege policies.
create table private.framing_sync_clock (business_id uuid primary key references public.businesses(id) on delete restrict,last_updated_at timestamptz not null);
revoke all on private.framing_sync_clock from public,anon,authenticated;
create function private.framing_next_version() returns trigger language plpgsql security definer set search_path='' as $$ declare v timestamptz; begin insert into private.framing_sync_clock as c(business_id,last_updated_at) values(new.business_id,pg_catalog.clock_timestamp()) on conflict(business_id) do update set last_updated_at=greatest(pg_catalog.clock_timestamp(),c.last_updated_at+interval '1 microsecond') returning last_updated_at into v; new.updated_at:=v; return new; end; $$;
revoke all on function private.framing_next_version() from public,anon,authenticated;
create trigger framing_settings_version before insert or update on public.framing_settings for each row execute function private.framing_next_version();
create trigger frame_moulding_version before insert or update on public.frame_mouldings for each row execute function private.framing_next_version();
create trigger frame_material_version before insert or update on public.frame_materials for each row execute function private.framing_next_version();
create trigger frame_quote_version before insert or update on public.frame_quotes for each row execute function private.framing_next_version();
create trigger frame_quote_item_version before insert or update on public.frame_quote_items for each row execute function private.framing_next_version();
create trigger frame_job_version before insert or update on public.frame_jobs for each row execute function private.framing_next_version();
create index frame_mouldings_updated_idx on public.frame_mouldings(business_id,updated_at,id); create index frame_materials_updated_idx on public.frame_materials(business_id,updated_at,id); create index frame_quotes_updated_idx on public.frame_quotes(business_id,updated_at,id); create index frame_quote_items_updated_idx on public.frame_quote_items(business_id,updated_at,id); create index frame_jobs_updated_idx on public.frame_jobs(business_id,updated_at,id);
drop policy framing_settings_write on public.framing_settings; drop policy frame_mouldings_access on public.frame_mouldings; drop policy frame_materials_access on public.frame_materials; drop policy frame_quotes_access on public.frame_quotes; drop policy frame_quote_items_access on public.frame_quote_items; drop policy frame_jobs_access on public.frame_jobs;
create policy framing_settings_admin on public.framing_settings for all to authenticated using(exists(select 1 from public.business_memberships m where m.business_id=framing_settings.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin'))) with check(exists(select 1 from public.business_memberships m where m.business_id=framing_settings.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin')));
create policy frame_mouldings_read on public.frame_mouldings for select to authenticated using(private.has_active_membership(business_id)); create policy frame_mouldings_admin on public.frame_mouldings for all to authenticated using(exists(select 1 from public.business_memberships m where m.business_id=frame_mouldings.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin'))) with check(exists(select 1 from public.business_memberships m where m.business_id=frame_mouldings.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin')));
create policy frame_materials_read on public.frame_materials for select to authenticated using(private.has_active_membership(business_id)); create policy frame_materials_admin on public.frame_materials for all to authenticated using(exists(select 1 from public.business_memberships m where m.business_id=frame_materials.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin'))) with check(exists(select 1 from public.business_memberships m where m.business_id=frame_materials.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin')));
create policy frame_quotes_member on public.frame_quotes for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id) and (created_by=(select auth.uid()) or exists(select 1 from public.business_memberships m where m.business_id=frame_quotes.business_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','admin','staff'))));
create policy frame_quote_items_member on public.frame_quote_items for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id)); create policy frame_jobs_member on public.frame_jobs for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id));
revoke all on public.framing_settings,public.frame_mouldings,public.frame_materials,public.frame_quotes,public.frame_quote_items,public.frame_jobs from authenticated; grant select,insert,update on public.framing_settings,public.frame_mouldings,public.frame_materials,public.frame_quotes,public.frame_quote_items,public.frame_jobs to authenticated;
